"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[92112],{78312:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>a,contentTitle:()=>r,default:()=>u,frontMatter:()=>s,metadata:()=>i,toc:()=>d});var h=n(31085),o=n(71184);const s={sidebar_position:8,slug:"/bible/Judith/Judith_8",title:"Judith 8",hide_table_of_contents:!0},r="Judith",i={id:"bible/Judith/Judith 8",title:"Judith 8",description:"Chapter 8",source:"@site/docs/bible/Judith/Judith 8.md",sourceDirName:"bible/Judith",slug:"/bible/Judith/Judith_8",permalink:"/bibleNotes/docs/bible/Judith/Judith_8",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/Judith/Judith 8.md",tags:[],version:"current",sidebarPosition:8,frontMatter:{sidebar_position:8,slug:"/bible/Judith/Judith_8",title:"Judith 8",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Judith 7",permalink:"/bibleNotes/docs/bible/Judith/Judith_7"},next:{title:"Judith 9",permalink:"/bibleNotes/docs/bible/Judith/Judith_9"}},a={},d=[{value:"Chapter 8",id:"chapter-8",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,o.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,h.jsxs)(h.Fragment,{children:[(0,h.jsx)(t.h1,{id:"judith",children:"Judith"}),"\n",(0,h.jsx)(t.h2,{id:"chapter-8",children:"Chapter 8"}),"\n",(0,h.jsx)(t.p,{children:"The character of Judith:  her discourse to the ancients."}),"\n",(0,h.jsx)(n,{verse:1,children:"Now it came to pass, when Judith a widow had heard these words, who was the daughter of Merari, the son of Idox, the son of Joseph, the son of Ozias, the son of Elai, the son of Jamnor, the son of Gedeon, the son of Raphaim, the son of Achitob, the son of Melchias, the son of Enan, the son of Nathanias, the son of Salathiel, the son of Simeon, the son of Ruben:"}),"\n",(0,h.jsx)(t.admonition,{type:"note",children:(0,h.jsx)(t.p,{children:"Note 1: Simeon the son of Ruben...In the Greek, it is the son of Israel. For Simeon the patriarch, from whom Judith descended, was not the son, but the brother of Ruben. It seems more probable that the Simeon and the Ruben here mentioned are not the patriarchs: but two of the descendants of the patriarch Simeon: and that the genealogy of Judith, recorded in this place, is not carried up so high as the patriarchs. No more than that of Elcana the father of Samuel, 1 Kings 1.1, and that of king Saul, 1 Kings 9.1."})}),"\n",(0,h.jsx)(n,{verse:2,children:"And her husband was Manasses, who died in the time of the barley harvest:"}),"\n",(0,h.jsx)(n,{verse:3,children:"For he was standing over them that bound sheaves in the field; and the heat came upon his head, and he died in Bethulia his own city, and was buried there with his fathers."}),"\n",(0,h.jsx)(n,{verse:4,children:"And Judith his relict was a widow now three years and six months."}),"\n",(0,h.jsx)(n,{verse:5,children:"And she made herself a private chamber in the upper part of her house, in which she abode shut up with her maids."}),"\n",(0,h.jsx)(n,{verse:6,children:"And she wore haircloth upon her loins, and fasted all the days of her life, except the sabbaths, and new moons, and the feasts of the house of Israel."}),"\n",(0,h.jsx)(n,{verse:7,children:"And she was exceedingly beautiful, and her husband left her great riches, and very many servants, and large possessions of herds of oxen, and flocks of sheep."}),"\n",(0,h.jsx)(n,{verse:8,children:"And she was greatly renowned among all, because she feared the Lord very much, neither was there any one that spoke an ill word of her."}),"\n",(0,h.jsx)(n,{verse:9,children:"When therefore she had heard that Ozias had promised that he would deliver up the city after the fifth day, she sent to the ancients Chabri and Charmi."}),"\n",(0,h.jsx)(n,{verse:10,children:"And they came to her, and she said to them: What is this word, by which Ozias hath consented to give up the city to the Assyrians, if within five days there come no aid to us?"}),"\n",(0,h.jsx)(n,{verse:11,children:"And who are you that tempt the Lord?"}),"\n",(0,h.jsx)(n,{verse:12,children:"This is not a word that may draw down mercy, but rather that may stir up wrath, and enkindle indignation."}),"\n",(0,h.jsx)(n,{verse:13,children:"You have set a time for the mercy of the Lord, and you have appointed him a day, according to your pleasure."}),"\n",(0,h.jsx)(n,{verse:14,children:"But forasmuch as the Lord is patient, let us be penitent for this same thing, and with many tears let us beg his pardon:"}),"\n",(0,h.jsx)(n,{verse:15,children:"For God will not threaten like man, nor be inflamed to anger like the son of man."}),"\n",(0,h.jsx)(n,{verse:16,children:"And therefore let us humble our souls before him, and continuing in an humble spirit, in his service:"}),"\n",(0,h.jsx)(n,{verse:17,children:"Let us ask the Lord with tears, that according to his will so he would shew his mercy to us: that as our heart is troubled by their pride, so also we may glorify in our humility."}),"\n",(0,h.jsx)(n,{verse:18,children:"For we have not followed the sins of our fathers, who forsook their God, and worshipped strange gods."}),"\n",(0,h.jsx)(n,{verse:19,children:"For which crime they were given up to their enemies, to the sword, and to pillage, and to confusion: but we know no other God but him."}),"\n",(0,h.jsx)(n,{verse:20,children:"Let us humbly wait for his consolation, and the Lord our God will require our blood of the afflictions of our enemies, and he will humble all the nations that shall rise up against us, and bring them to disgrace."}),"\n",(0,h.jsx)(n,{verse:21,children:"And now, brethren, as you are the ancients among the people of God, and their very soul resteth upon you: comfort their hearts by your speech, that they may be mindful how our fathers were tempted that they might be proved, whether they worshipped their God truly."}),"\n",(0,h.jsx)(n,{verse:22,children:"They must remember how our father Abraham was tempted, and being proved by many tribulations, was made the friend of God."}),"\n",(0,h.jsx)(n,{verse:23,children:"So Isaac, so Jacob, so Moses, and all that have pleased God, passed through many tribulations, remaining faithful."}),"\n",(0,h.jsx)(n,{verse:24,children:"But they that did not receive the trials with the fear of the Lord, but uttered their impatience and the reproach of their murmuring against the Lord,"}),"\n",(0,h.jsx)(n,{verse:25,children:"Were destroyed by the destroyer, and perished by serpents."}),"\n",(0,h.jsx)(n,{verse:26,children:"As for us therefore let us not revenge ourselves for these things which we suffer."}),"\n",(0,h.jsx)(n,{verse:27,children:"But esteeming these very punishments to be less than our sins deserve, let us believe that these scourges of the Lord, with which like servants we are chastised, have happened for our amendment, and not for our destruction."}),"\n",(0,h.jsx)(n,{verse:28,children:"And Ozias and the ancients said to her: All things which thou hast spoken are true, and there is nothing to be reprehended in thy words."}),"\n",(0,h.jsx)(n,{verse:29,children:"Now therefore pray for us, for thou art a holy woman, and one fearing God."}),"\n",(0,h.jsx)(n,{verse:30,children:"And Judith said to them: As you know that what I have been able to say is of God:"}),"\n",(0,h.jsx)(n,{verse:31,children:"So that which I intend to do prove ye if it be of God, and pray that God may strengthen my design."}),"\n",(0,h.jsx)(n,{verse:32,children:"You shall stand at the gate this night, and I will go out with my maidservant: and pray ye, that as you have said, in five days the Lord may look down upon his people Israel."}),"\n",(0,h.jsx)(n,{verse:33,children:"But I desire that you search not into what I am doing, and till I bring you word let nothing else be done but to pray for me to the Lord our God."}),"\n",(0,h.jsx)(n,{verse:34,children:"And Ozias the prince of Juda said to her: Go in peace, and the Lord be with thee to take revenge of our enemies. So returning they departed."})]})}function u(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,h.jsx)(t,{...e,children:(0,h.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>r,x:()=>i});var h=n(14041);const o={},s=h.createContext(o);function r(e){const t=h.useContext(s);return h.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),h.createElement(s.Provider,{value:t},e.children)}}}]);